import {test} from 'node:test';import assert from 'node:assert/strict';import {Vec2} from 'planck';import {Simulation} from '../src/simulation/world';import {applyChaos} from '../src/chaos/registry';import {FROG_CHAOS as D} from '../src/chaos/frog-chaos';import {capture,restore} from '../src/simulation/state';import {readFileSync} from 'node:fs';import {createHash} from 'node:crypto';
test('real Swap Hop grants 45 ticks to both frogs, persists through snapshots, and expires exactly',()=>{const s=new Simulation();applyChaos(s,['swap_hop']);s.frogs.forEach((f,i)=>f.body.setTransform(Vec2(6+i*20,19),0));s.tick=D.swapPeriod-D.swapWarning;s.frogChaos.before();s.tick=D.swapPeriod;s.frogChaos.before();assert.equal(D.swapProtection,45);assert.ok(s.frogs.every(f=>f.swapTick===720&&f.swapProtectedUntil===765));const c=new Simulation();applyChaos(c,['swap_hop']);restore(c,capture(s));for(const sim of[s,c]){for(const t of[720,741,764]){sim.tick=t;assert.deepEqual(sim.frogChaos.ruleContacts([[0,1],[1,0]]),[]);}sim.tick=765;assert.deepEqual(sim.frogChaos.ruleContacts([[0,1]]),[[0,1]]);applyChaos(sim,[]);assert.deepEqual(sim.frogChaos.ruleContacts([[0,1]]),[[0,1]]);}});
test('duration is the only runtime change; approved arrow, physics, bots and controls remain byte-identical',()=>{const m=JSON.parse(readFileSync('docs/swap-protection-preservation.json','utf8')),h=(v:any)=>createHash('sha256').update(v).digest('hex');assert.equal(readFileSync('src/chaos/frog-chaos.ts','utf8').replace('swapProtection:45','swapProtection:21'),m.files['src/chaos/frog-chaos.ts'].original);for(const[p,v]of Object.entries(m.protected))assert.equal(h(readFileSync(p)),v,p);for(const[p,v]of Object.entries(m.files)as[string,any][])assert.equal(h(readFileSync(p)),v.afterSha256,p);});

